#!/usr/bin/env bash
# Phase 2 paired FIM evaluation on the exact window-FIM training layout.
#
# Runs the same deterministic train-window holes twice:
#   greedy              learned EOS + parser reconnection, no syntax mask
#   greedy_full_masked  learned EOS + parser reconnection, full H.264 syntax mask
#
# The learned-EOS masked run permits EOS only when the generated middle legally
# reconnects to the fixed orphan/suffix. Parser reconnection does not use GT length:
# it stops at the first generated byte where the fixed suffix completes the parse.
#
# Usage:
#   ./scripts/hpc/vulcan/phase2_fim/eval_fim.sh
#   CKPT=step-00006000 NUM_CLIPS=100 ./scripts/hpc/vulcan/phase2_fim/eval_fim.sh
set -euo pipefail

DATA=${DATA:-/fs/nexus-projects/time-control-videogen/OpenVid-1M_Data/data-avclm}
OUT_DIR=${OUT_DIR:-${DATA}/runs/byte-phase2-fim-1000v-85m}
CKPT=${CKPT:-step-00006000}
NUM_CLIPS=${NUM_CLIPS:-20}  # Match the existing AR eval.sh by default.
MAX_MANIFEST_ROWS=${MAX_MANIFEST_ROWS:-1000}
SEED=${SEED:-42}
DEVICE=${DEVICE:-cuda}
PYTHON_BIN=${PYTHON_BIN:-python}
MAX_GEN_BYTES=${MAX_GEN_BYTES:-4096}
MAX_WINDOW_BYTES=${MAX_WINDOW_BYTES:-16384}
SLICE_LAYOUT=${SLICE_LAYOUT:-macroblock}
SLICE_MAX_MBS=${SLICE_MAX_MBS:-1}

CHECKPOINT_DIR="${OUT_DIR}/${CKPT}"
if [[ ! -d "${CHECKPOINT_DIR}" ]]; then
    echo "Checkpoint does not exist: ${CHECKPOINT_DIR}" >&2
    exit 1
fi

echo "[phase2 FIM eval] checkpoint=${CKPT} clips=${NUM_CLIPS} seed=${SEED}"

EVAL=scripts/byte/eval/eval_fim_avclm.py
COMMON=(
    "${DATA}/manifest.jsonl"
    --nal-index-path "${DATA}/nal_index.sqlite"
    --checkpoint-dirs "${CHECKPOINT_DIR}"
    --train-split-file "${OUT_DIR}/train_split.json"
    --eval-split train
    --device "${DEVICE}"
    --max-manifest-rows "${MAX_MANIFEST_ROWS}"
    --num-clips "${NUM_CLIPS}"
    --num-visualizations 8
    --viz-fps 6
    --seed "${SEED}"
    --max-window-bytes "${MAX_WINDOW_BYTES}"
    --window-min-frames 2
    --fim-format psm
    --use-eos
    --fim-min-gap 64
    --fim-max-gap 1400
    --slice-header-guard-bytes 64
    --slice-layout "${SLICE_LAYOUT}"
    --stop-modes learned_eos parser_reconnect
    --temperature 0
    --top-k 0
    --top-p 1.0
    --max-gen-bytes "${MAX_GEN_BYTES}"
    --decode
    --timeout-sec 60
    --save-streams
)
if [[ "${SLICE_LAYOUT}" == "macroblock" ]]; then
    COMMON+=(--slice-max-mbs "${SLICE_MAX_MBS}")
fi

EVAL_ROOT="${OUT_DIR}/eval_fim/train/${CKPT}"

run() {
    local name="$1"
    shift
    local dir="${EVAL_ROOT}/${name}"
    # metrics.jsonl and sample_details.jsonl are append-only.  Mixing reruns in one
    # directory would make the summary disagree with the saved configuration.
    if [[ -d "${dir}" ]]; then
        echo "[clean] removing previous ${dir}"
        rm -rf "${dir}"
    fi

    echo "===================== [FIM/${name}] ====================="
    "${PYTHON_BIN}" "${EVAL}" "${COMMON[@]}" --out-dir "${dir}" "$@"
}

run greedy
run greedy_full_masked --mask-illegal-bytes

echo
echo "===================== FIM paired summary ====================="
"${PYTHON_BIN}" - "${EVAL_ROOT}" greedy greedy_full_masked <<'PY'
import json
import sys
from pathlib import Path

root = Path(sys.argv[1])
names = sys.argv[2:]

header = (
    f"{'variant':<20} {'stop':<16} {'n':>4} {'end2end':>8} "
    f"{'terminate':>9} {'decode':>8} {'frames':>11} {'bytes':>17} "
    f"{'tf_acc':>9} {'psnr':>8} {'desync_top':<18}"
)
print(header)
print("-" * len(header))

for name in names:
    path = root / name / "metrics.jsonl"
    if not path.exists():
        print(f"{name:<20} (missing metrics.jsonl)")
        continue
    for line in path.open():
        row = json.loads(line)
        success = row.get("success_rate")
        success_text = "-" if success is None else f"{success:.3f}"
        termination = row.get("termination_success_rate")
        termination_text = "-" if termination is None else f"{termination:.3f}"
        decode = row.get("repair_decode_success_rate")
        decode_text = "-" if decode is None else f"{decode:.3f}"
        tf_acc = row.get("tf_byte_acc_mean")
        tf_text = "-" if tf_acc is None else f"{tf_acc:.4f}"
        psnr = row.get("cont_psnr_mean")
        psnr_text = "-" if psnr is None else f"{psnr:.2f}"
        frames = f"{row.get('completed_frames_total', 0)}/{row.get('target_frames_total', 0)}"
        byte_counts = f"{row.get('completed_bytes_total', 0)}/{row.get('target_bytes_total', 0)}"
        print(
            f"{name:<20} {row.get('stop_mode', '-'):<16} {row.get('num_clips', 0):>4} "
            f"{success_text:>8} {termination_text:>9} {decode_text:>8} "
            f"{frames:>11} {byte_counts:>17} {tf_text:>9} {psnr_text:>8} "
            f"{str(row.get('desync_region_top') or '-'): <18}"
        )

print()
print("end2end requires both autonomous stopping and strict decode success.")
print("parser_reconnect is the deployable length-free stopping compromise.")
print("Outputs:", root)
PY
